const caps = groups.flatMap(([prefix,group,rr,jj,authority,evidence,status,items])=>items.split(';').map((capability,i)=>({id:`${prefix}-${String(i+1).padStart(2,'0')}`,group,capability,roles:rr.map(r=>roles[r]),stages:jj.map(j=>stages[j]),classification:status,authority,evidence:evidence.split(';'),source:sourceMap[prefix],evidenceScope:'Group evidence is a discovery pointer; it does not prove every leaf capability. Individual execution proof remains required.',layers:{domain:'UNVERIFIED',persistence:'UNVERIFIED',api:'UNVERIFIED',permissions:'UNVERIFIED',ui:'UNVERIFIED',actualOutput:'UNVERIFIED',browser:'NOT_AUDITED',handoff:'UNVERIFIED'}})));
