// ── AUDIT-AUTHORITY CORRECTION — ENG-04, from discovery rather than from the capability name ──
//
// The frozen register gave ENG-04 the authority "Engineering / DocControl", written from what the
// capability is CALLED. Discovery found the governed record elsewhere, and the correction is recorded
// here with the frozen value PRESERVED rather than overwritten, because a capability must never move
// between contexts silently.
//
// The evidence: Quality’s Material Approval Request is the only register that models a material
// (manufacturer, supplier, specification), carries the consultant’s decision with who recorded it and
// when, keeps a revision chain, and is consumed by a procurement rule. DocControl’s submittals are
// controlled DOCUMENTS with A/B/C/D review codes. Engineering’s register could mark a submittal
// "approved" with no reviewer, no comments and nothing downstream reading it — its material writer is
// now refused outright.
const eng04 = caps.find(c=>c.id==='ENG-04');
eng04.authorityFrozen = eng04.authority;
eng04.authority = 'Quality (material approval decision) / Engineering (originating technical context)';
eng04.authorityCorrection = 'Corrected from the frozen "Engineering / DocControl" after discovery. Quality MAR is the canonical material-approval DECISION authority: it alone models the material, the consultant decision, the recording actor and the revision chain, and it alone is consumed downstream. DocControl remains the controlled-document / register / transmittal authority for a document representation. Engineering is the originating technical context and is NOT an independent material-approval writer — its submittalType material is refused. Historical Engineering material submittals are preserved and are not rewritten into Quality MARs.';

function set(id,status,behavior,proof,layer){const c=caps.find(c=>c.id===id);Object.assign(c,{classification:status,currentBehavior:behavior,acceptanceProof:proof});if(layer)c.layers[layer]='PARTIAL';}
